const body = $input.first().json.body || {};

const tenant_id = body.tenant_id;
const user_id = body.user_id;
const provider = body.provider;

// Validation
const errors = [];
if (!tenant_id) errors.push('tenant_id requis');
if (!user_id) errors.push('user_id requis');
if (!provider) errors.push('provider requis');

const validProviders = ['lichess'];
if (provider && !validProviders.includes(provider)) {
  errors.push(`provider invalide: ${provider}. Valeurs: ${validProviders.join(', ')}`);
}

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: { code: 400, message: errors.join(', '), status: 'BAD_REQUEST' }
    }
  };
}

return {
  json: {
    valid: true,
    tenant_id,
    user_id,
    provider
  }
};

const input = $('Validate Input').first().json;
const response = $input.first().json;

const statusCode = response.statusCode || 200;
const body = response.body || response;

if (statusCode >= 400 || body.success === false) {
  return {
    json: {
      success: false,
      error: {
        code: statusCode,
        message: body.error?.message || 'Erreur API',
        details: body
      }
    }
  };
}

const data = body.data;

// No token found
if (data === null) {
  return {
    json: {
      success: true,
      has_token: false,
      provider: input.provider,
      message: 'Aucun token OAuth trouve pour ce provider'
    }
  };
}

// Token found
return {
  json: {
    success: true,
    has_token: true,
    provider: input.provider,
    access_token: data.access_token,
    refresh_token: data.refresh_token || null,
    expires_at: data.expires_at,
    is_expired: data.is_expired || false,
    scope: data.scope,
    provider_user_id: data.provider_user_id
  }
};
